/**
 * The marketing video for xplainer.video, one component per narration segment.
 *
 * Seven scenes: a title card that doubles as the thumbnail, the cost of the usual way, the five
 * tools an agent gets, the measured-speech idea that is the actual differentiator, what people
 * explain with it, the three setup commands, and the local-and-open close.
 *
 * **The title scene is settled at frame 0 on purpose.** `explainer_still` at frame 0 is what becomes
 * the README's poster image, so the first frame has to be the composed card rather than the first
 * frame of a fade. Every other scene enters with the shared `rise`.
 *
 * Durations are not here and cannot be: the engine lays out one Sequence per measured narration
 * segment, so each scene's length is whatever its sentence took to say. What a scene controls is
 * only how it fills the time it is given, which is why the animations are all short entries that
 * settle rather than timelines that assume a length.
 */

import React from "react";
import { AbsoluteFill, interpolate, useCurrentFrame, useVideoConfig } from "remotion";
import type { LayerProps, SceneMap, SceneProps } from "./Video";
import { Icon, type IconName } from "./Icons";
import { Badge, Card, Caret, Chip, Code, Kicker, Lead, rise, Rule, Stage, Title } from "./scenes/Chrome";
import { C, MONO_STYLE, T } from "./scenes/Theme";

/* ────────────────────────────── the layer behind everything ───────────────────────────── */

/**
 * Two slow glows and a faint grid, spanning the whole video.
 *
 * It exists so that seven flat cards on one background colour do not read as a slide deck: the
 * glows drift on a period longer than any single scene, so the frame is never quite the same twice
 * even while a scene holds still. The grid is at 3% because at 6% it moires against the caption
 * band on a downscaled README player.
 */
export const Backdrop: React.FC<LayerProps> = () => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const drift = (period: number, span: number) =>
    Math.sin((frame / period) * Math.PI * 2) * span;

  return (
    <AbsoluteFill style={{ backgroundColor: C.bg }}>
      <AbsoluteFill
        style={{
          backgroundImage: `linear-gradient(${C.hairline} 1px, transparent 1px), linear-gradient(90deg, ${C.hairline} 1px, transparent 1px)`,
          backgroundSize: "96px 96px",
          opacity: 0.16,
        }}
      />
      <AbsoluteFill
        style={{
          background: `radial-gradient(760px circle at ${width * 0.18 + drift(420, 70)}px ${height * 0.2 + drift(520, 50)}px, ${C.blue}26, transparent 70%)`,
        }}
      />
      <AbsoluteFill
        style={{
          background: `radial-gradient(820px circle at ${width * 0.86 + drift(500, -80)}px ${height * 0.78 + drift(460, 60)}px, ${C.violet}20, transparent 70%)`,
        }}
      />
      {/* A vignette, so the caption pill always has something darker behind it. */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(120% 90% at 50% 40%, transparent 40%, ${C.bg}D9 100%)`,
        }}
      />
    </AbsoluteFill>
  );
};

/* ──────────────────────────────────── 1. the title card ───────────────────────────────── */

const TitleCard: React.FC<SceneProps> = () => {
  const frame = useCurrentFrame();
  // No entry animation — this frame is the thumbnail. The only motion is a slow sheen across the
  // wordmark, which is legible at frame 0 either way.
  const sheen = interpolate(frame % 150, [0, 150], [-40, 140]);

  return (
    <Stage center>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 18,
          padding: "16px 32px",
          borderRadius: 999,
          border: `2px solid ${C.green}44`,
          backgroundColor: `${C.green}14`,
        }}
      >
        <Icon name="Check" size={30} color={C.green} />
        <span style={{ ...T.label, color: C.green, letterSpacing: 2 }}>
          OPEN SOURCE &nbsp;·&nbsp; APACHE-2.0 &nbsp;·&nbsp; RENDERS OFFLINE
        </span>
      </div>

      <div
        style={{
          ...T.wordmark,
          marginTop: 44,
          backgroundImage: `linear-gradient(100deg, ${C.ink} ${sheen - 40}%, #FFFFFF ${sheen}%, ${C.ink} ${sheen + 40}%)`,
          backgroundClip: "text",
          WebkitBackgroundClip: "text",
          color: "transparent",
        }}
      >
        xplainer<span style={{ color: C.blue, WebkitTextFillColor: C.blue }}>.video</span>
      </div>

      <div style={{ ...T.lead, color: C.inkSoft, marginTop: 18, maxWidth: 1180 }}>
        Your agents found the answer. Now see the explanation.
      </div>

      <div style={{ display: "flex", gap: 20, marginTop: 52 }}>
        <Chip name="Anthropic" color={C.amber}>
          Claude Code
        </Chip>
        <Chip name="Openai" color={C.green}>
          Codex
        </Chip>
        <Chip name="Cpu" color={C.blue}>
          local render
        </Chip>
        <Chip name="Mic" color={C.violet}>
          built-in voice
        </Chip>
      </div>
    </Stage>
  );
};

/* ─────────────────────────────────── 2. the usual way ─────────────────────────────────── */

const COSTS: { name: IconName; label: string; note: string; you?: boolean }[] = [
  { name: "Terminal", label: "Agent one", note: "traced the race to a retry" },
  { name: "Bug", label: "Agent two", note: "found the null path" },
  { name: "GitPullRequest", label: "Agent three", note: "mid-refactor, still going" },
  { name: "BookOpen", label: "You", note: "rebuild all three from chat", you: true },
];

const Problem: React.FC<SceneProps> = () => {
  const frame = useCurrentFrame();
  return (
    <Stage>
      <div style={rise(frame, 0)}>
        <Kicker color={C.rose}>the real cost</Kicker>
        <Title>Catching up. Over and over.</Title>
        <Rule color={C.rose} />
      </div>
      <div style={{ display: "flex", gap: 24, marginTop: 62 }}>
        {COSTS.map((cost, index) => (
          <Card
            key={cost.label}
            accent={cost.you === true ? C.rose : undefined}
            style={{
              ...rise(frame, 8 + index * 5),
              flex: 1,
              minWidth: 0,
              // The three agents are working; the fourth card is the queue they leave behind, so it
              // is the only one that carries the accent.
              backgroundColor: cost.you === true ? `${C.rose}14` : C.surface,
            }}
          >
            <Badge name={cost.name} color={cost.you === true ? C.rose : C.muted} size={72} />
            <div
              style={{
                ...T.body,
                fontWeight: 700,
                marginTop: 26,
                color: cost.you === true ? C.ink : C.inkSoft,
              }}
            >
              {cost.label}
            </div>
            <div style={{ ...T.label, color: C.muted, marginTop: 12, lineHeight: 1.35 }}>
              {cost.note}
            </div>
          </Card>
        ))}
      </div>
    </Stage>
  );
};

/* ────────────────────────────── 2b. what arrives instead ──────────────────────────────── */

/**
 * The turn: the same finding, handed over as something you watch rather than reassemble.
 *
 * It draws the artefact itself — a player with a scrubber, a waveform and a caption — because the
 * claim of this scene is about the *form* the answer takes, and a list of adjectives would be the
 * thing the video is arguing against.
 */
const Answer: React.FC<SceneProps> = () => {
  const frame = useCurrentFrame();
  const played = interpolate(frame, [10, 80], [0.06, 0.62], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <Stage>
      <div style={rise(frame, 0)}>
        <Kicker color={C.green}>instead</Kicker>
        <Title>Let it show you.</Title>
        <Rule color={C.green} />
      </div>

      <Card accent={C.green} style={{ ...rise(frame, 6), marginTop: 44, padding: 30 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 30 }}>
          <div
            style={{
              width: 104,
              height: 104,
              borderRadius: 52,
              backgroundColor: `${C.green}1F`,
              border: `2px solid ${C.green}66`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
            }}
          >
            <Icon name="Play" size={44} color={C.green} />
          </div>

          <div style={{ flex: 1, minWidth: 0 }}>
            {/* The narration, drawn as the thing that carries the explanation. */}
            <div style={{ display: "flex", alignItems: "center", gap: 3, height: 64 }}>
              {Array.from({ length: 92 }, (_, index) => {
                const heard = index / 92 < played;
                return (
                  <div
                    key={index}
                    style={{
                      flex: 1,
                      height: `${amplitude(index) * 100}%`,
                      borderRadius: 3,
                      backgroundColor: heard ? C.green : C.hairline,
                    }}
                  />
                );
              })}
            </div>
            <div
              style={{
                height: 8,
                borderRadius: 4,
                backgroundColor: C.hairline,
                marginTop: 22,
                overflow: "hidden",
              }}
            >
              <div style={{ width: `${played * 100}%`, height: "100%", backgroundColor: C.green }} />
            </div>
            <div
              style={{
                ...T.label,
                color: C.muted,
                marginTop: 18,
                display: "flex",
                justifyContent: "space-between",
              }}
            >
              <span>narrated, with captions</span>
              <span style={{ ...MONO_STYLE, fontSize: 26 }}>01:30</span>
            </div>
          </div>
        </div>
      </Card>

      <Lead max={1560}>
        One finding, handed over as ninety seconds you can watch — while the other agents keep
        working.
      </Lead>
    </Stage>
  );
};

/* ─────────────────────────────────── 3. the five tools ────────────────────────────────── */

const TOOLS: { name: IconName; tool: string; what: string }[] = [
  { name: "FolderOpen", tool: "create", what: "scaffold" },
  { name: "Type", tool: "put_source", what: "scenes as code" },
  { name: "Mic", tool: "narrate", what: "voice + timings" },
  { name: "Image", tool: "still", what: "check a frame" },
  { name: "Film", tool: "render", what: "the MP4" },
];

const Pipeline: React.FC<SceneProps> = () => {
  const frame = useCurrentFrame();
  return (
    <Stage>
      <div style={rise(frame, 0)}>
        <Kicker>what your agent gets</Kicker>
        <Title>Five tools over MCP</Title>
        <Rule />
      </div>

      <div style={{ display: "flex", alignItems: "flex-start", marginTop: 66, width: "100%" }}>
        {TOOLS.map((step, index) => {
          const appear = 8 + index * 6;
          // A pulse runs along the chain once every 90 frames, one node at a time.
          const pulse = interpolate((frame - index * 6) % 90, [0, 10, 22], [0, 1, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          return (
            <React.Fragment key={step.tool}>
              {index > 0 ? (
                // The connector is its own flex item so it absorbs the slack between nodes, and
                // its margin puts it at the vertical centre of the tiles rather than of the column.
                <div
                  style={{
                    ...rise(frame, appear, 0),
                    flex: 1,
                    height: 4,
                    minWidth: 16,
                    marginTop: 57,
                    borderRadius: 2,
                    backgroundColor: C.hairline,
                  }}
                />
              ) : null}
              <div
                style={{
                  ...rise(frame, appear),
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  flexShrink: 0,
                }}
              >
                <div
                  style={{
                    width: 118,
                    height: 118,
                    borderRadius: 30,
                    backgroundColor: C.surface,
                    border: `2px solid ${C.blue}${pulse > 0.5 ? "CC" : "3D"}`,
                    boxShadow: `0 0 ${34 * pulse}px ${C.blue}${pulse > 0.2 ? "66" : "00"}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <Icon name={step.name} size={54} color={C.blue} />
                </div>
                <div
                  style={{
                    ...MONO_STYLE,
                    fontSize: 29,
                    fontWeight: 600,
                    marginTop: 24,
                    color: C.ink,
                    whiteSpace: "nowrap",
                  }}
                >
                  {step.tool}
                </div>
                <div
                  style={{
                    fontSize: 26,
                    fontWeight: 600,
                    color: C.muted,
                    marginTop: 8,
                    whiteSpace: "nowrap",
                  }}
                >
                  {step.what}
                </div>
              </div>
            </React.Fragment>
          );
        })}
      </div>

      <Lead max={1500}>
        A plugin for Claude Code and Codex. The agent writes real Remotion components, and these
        five carry them from an empty folder to a finished file.
      </Lead>
    </Stage>
  );
};

/* ──────────────────────────── 4. measured speech, then picture ────────────────────────── */

/** A deterministic pseudo-waveform: stable across renders, and it never needs an asset. */
function amplitude(index: number): number {
  const a = Math.sin(index * 0.7) * 0.5 + Math.sin(index * 1.9) * 0.28 + Math.sin(index * 3.3) * 0.22;
  return 0.22 + Math.abs(a) * 0.78;
}

const BARS = 104;
const SCENE_SPANS = [
  { label: "scene 1", share: 0.3, color: C.blue },
  { label: "scene 2", share: 0.42, color: C.violet },
  { label: "scene 3", share: 0.28, color: C.green },
];

const Measured: React.FC<SceneProps> = () => {
  const frame = useCurrentFrame();
  const drawn = interpolate(frame, [6, 42], [0, BARS], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const grow = interpolate(frame, [40, 66], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <Stage>
      <div style={rise(frame, 0)}>
        <Kicker color={C.amber}>why it lines up</Kicker>
        <Title>The speech is measured first.</Title>
        <Rule color={C.amber} />
      </div>

      <Card accent={C.amber} style={{ ...rise(frame, 6), marginTop: 50, padding: 38 }}>
        {/* The waveform, drawn left to right as if it were being analysed. */}
        <div style={{ display: "flex", alignItems: "center", gap: 3, height: 140 }}>
          {Array.from({ length: BARS }, (_, index) => {
            const on = index < drawn;
            return (
              <div
                key={index}
                style={{
                  flex: 1,
                  height: `${amplitude(index) * 100}%`,
                  borderRadius: 3,
                  backgroundColor: on ? C.amber : C.hairline,
                  opacity: on ? 1 : 0.5,
                }}
              />
            );
          })}
        </div>

        {/* Word boundaries, the thing a timestamp per word actually gives you. */}
        <div style={{ display: "flex", gap: 3, marginTop: 16, height: 24 }}>
          {Array.from({ length: BARS }, (_, index) => (
            <div key={index} style={{ flex: 1, display: "flex", justifyContent: "center" }}>
              {/* A 3px bar inside a ~7px slot. At the slot's own width these read as dots, which
                  says nothing; a tick reads as a boundary between two words. */}
              <div
                style={{
                  width: 3,
                  height: "100%",
                  borderRadius: 2,
                  backgroundColor: index % 7 === 0 && index < drawn ? C.ink : "transparent",
                }}
              />
            </div>
          ))}
        </div>

        {/* Durations derived from those boundaries, not chosen. */}
        <div style={{ display: "flex", gap: 12, marginTop: 26 }}>
          {SCENE_SPANS.map((span) => (
            <div key={span.label} style={{ flexGrow: span.share, flexBasis: 0 }}>
              <div
                style={{
                  height: 46,
                  borderRadius: 10,
                  backgroundColor: `${span.color}2E`,
                  border: `2px solid ${span.color}99`,
                  transform: `scaleX(${grow})`,
                  transformOrigin: "left center",
                }}
              />
              <div
                style={{
                  ...MONO_STYLE,
                  fontSize: 26,
                  fontWeight: 600,
                  color: span.color,
                  marginTop: 12,
                  opacity: grow,
                  whiteSpace: "nowrap",
                }}
              >
                {span.label}
              </div>
            </div>
          ))}
        </div>
      </Card>

      <Lead max={1560}>
        A timestamp on every word, so scene lengths are derived and the captions are already in sync
        before the first frame is drawn.
      </Lead>
    </Stage>
  );
};

/* ─────────────────────────────────── 5. what people explain ───────────────────────────── */

const USES: { name: IconName; title: string; note: string; color: string }[] = [
  { name: "Bug", title: "A race condition", note: "across three services", color: C.rose },
  { name: "Gauge", title: "Last night's outage", note: "a post-mortem people watch", color: C.amber },
  { name: "Cpu", title: "The architecture", note: "only two people hold it", color: C.violet },
  { name: "GitPullRequest", title: "A handoff", note: "agent to agent, or to you", color: C.green },
  { name: "Sparkles", title: "A design you are weighing", note: "thought through out loud", color: C.blue },
  { name: "GraduationCap", title: "Week one", note: "onboarding that stays current", color: C.blue },
];

const Uses: React.FC<SceneProps> = () => {
  const frame = useCurrentFrame();
  return (
    <Stage>
      <div style={rise(frame, 0)}>
        <Kicker color={C.green}>where it earns its keep</Kicker>
        {/* h2, not h1: this is the longest heading in the video and wraps at h1, which pushes the
            six cards into the caption band. */}
        <Title style={{ ...T.h2 }}>Exactly where text is worst.</Title>
      </div>
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
          gap: 22,
          marginTop: 52,
        }}
      >
        {USES.map((use, index) => (
          <Card
            key={use.title}
            accent={use.color}
            style={{ ...rise(frame, 6 + index * 4), display: "flex", gap: 24, alignItems: "center" }}
          >
            <Badge name={use.name} color={use.color} size={76} />
            <div style={{ minWidth: 0 }}>
              <div style={{ fontSize: 38, fontWeight: 700 }}>{use.title}</div>
              <div style={{ fontSize: 27, fontWeight: 600, color: C.muted, marginTop: 8 }}>
                {use.note}
              </div>
            </div>
          </Card>
        ))}
      </div>
    </Stage>
  );
};

/* ────────────────────────────────────── 6. the setup ──────────────────────────────────── */

const COMMANDS = [
  { text: "npm i -g xplainer", note: "the CLI" },
  { text: "xplainer setup", note: "browser + voice, once" },
  { text: "xplainer connect claude --spawn", note: "the MCP entry and the skill" },
];

/** Characters per frame, so a long command does not take longer than its sentence. */
const TYPE_RATE = 2.2;

const Setup: React.FC<SceneProps> = () => {
  const frame = useCurrentFrame();
  // Each line starts after the one above has finished typing.
  const starts: number[] = [];
  let cursor = 10;
  for (const command of COMMANDS) {
    starts.push(cursor);
    cursor += Math.ceil(command.text.length / TYPE_RATE) + 12;
  }

  return (
    <Stage>
      <div style={rise(frame, 0)}>
        <Kicker color={C.green}>setup</Kicker>
        <Title>Three commands.</Title>
        <Rule color={C.green} />
      </div>

      <Card style={{ ...rise(frame, 4), marginTop: 46, padding: 0, overflow: "hidden" }}>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 12,
            padding: "20px 28px",
            borderBottom: `2px solid ${C.hairline}`,
            backgroundColor: C.surfaceLift,
          }}
        >
          {[C.rose, C.amber, C.green].map((dot) => (
            <div
              key={dot}
              style={{ width: 18, height: 18, borderRadius: 9, backgroundColor: `${dot}CC` }}
            />
          ))}
          <span style={{ ...MONO_STYLE, fontSize: 26, color: C.muted, marginLeft: 16 }}>
            your terminal
          </span>
        </div>

        <div style={{ padding: "34px 38px" }}>
          {COMMANDS.map((command, index) => {
            const typed = Math.max(
              0,
              Math.min(command.text.length, Math.floor((frame - starts[index]) * TYPE_RATE)),
            );
            if (typed === 0) {
              return <div key={command.text} style={{ height: 74 }} />;
            }
            const complete = typed >= command.text.length;
            return (
              <div
                key={command.text}
                style={{ display: "flex", alignItems: "baseline", gap: 18, height: 74 }}
              >
                <Code color={C.green}>$</Code>
                <Code>{command.text.slice(0, typed)}</Code>
                {complete ? null : <Caret />}
                {complete ? (
                  <span
                    style={{
                      fontSize: 26,
                      fontWeight: 600,
                      color: C.muted,
                      marginLeft: "auto",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {command.note}
                  </span>
                ) : null}
              </div>
            );
          })}
        </div>
      </Card>

      <div
        style={{
          ...rise(frame, Math.max(...starts) + 22),
          display: "flex",
          alignItems: "center",
          gap: 20,
          marginTop: 34,
        }}
      >
        <Icon name="Sparkles" size={40} color={C.amber} />
        <span style={{ ...T.lead, color: C.inkSoft }}>
          then ask: <span style={{ color: C.ink, fontWeight: 700 }}>
            &ldquo;explain our retry logic as a ninety-second video&rdquo;
          </span>
        </span>
      </div>
    </Stage>
  );
};

/* ──────────────────────────────────────── 7. the close ────────────────────────────────── */

const Close: React.FC<SceneProps> = () => {
  const frame = useCurrentFrame();
  return (
    <Stage center>
      <div style={rise(frame, 0)}>
        <Title style={{ ...T.h2, marginTop: 0 }}>
          Nothing is uploaded.
          <br />
          Nothing renders anywhere but here.
        </Title>
      </div>

      <div style={{ ...rise(frame, 10), display: "flex", gap: 20, marginTop: 52 }}>
        <Chip name="Package" color={C.blue}>
          npm i -g xplainer
        </Chip>
        <Chip name="Cpu" color={C.violet}>
          your GPU, your disk
        </Chip>
        <Chip name="Check" color={C.green}>
          Apache-2.0
        </Chip>
      </div>

      <div
        style={{
          ...rise(frame, 18),
          ...MONO_STYLE,
          fontSize: 40,
          fontWeight: 600,
          color: C.inkSoft,
          marginTop: 56,
        }}
      >
        github.com/BrewMyTech/xplainer.video
      </div>

      <div style={{ ...rise(frame, 24), ...T.label, color: C.muted, marginTop: 26 }}>
        this video was made by an agent, with the tools it is about
      </div>
    </Stage>
  );
};

export const scenes: SceneMap = {
  title: TitleCard,
  problem: Problem,
  answer: Answer,
  pipeline: Pipeline,
  measured: Measured,
  uses: Uses,
  setup: Setup,
  close: Close,
};

/**
 * The pieces every scene is built from, so the seven of them share one grammar.
 *
 * `rise` is the only entry animation in the video, deliberately: one easing, one distance, one
 * duration, varied by a stagger index. Seven scenes each inventing their own motion is what makes a
 * generated video feel generated.
 *
 * It is also written so that `delay = 0` is fully settled at frame 0 rather than invisible. The
 * first frame of the composition is the video's thumbnail, and a title card that fades up from
 * black has nothing to show at the moment it is judged.
 */

import { AbsoluteFill, Easing, interpolate, useCurrentFrame } from "remotion";
import { Icon, type IconName } from "../Icons";
import { C, CAPTION_SAFE, FONT, MONO_STYLE, T } from "./Theme";

const EASE = Easing.bezier(0.16, 1, 0.3, 1);

/** Settled-at-`delay+18` entry: opacity and a small lift, both from the same curve. */
export function rise(frame: number, delay = 0, distance = 34) {
  const t = interpolate(frame, [delay, delay + 18], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: EASE,
  });
  return { opacity: t, transform: `translateY(${(1 - t) * distance}px)` };
}

/** The frame every scene draws into: consistent margins, and out of the caption band. */
export const Stage: React.FC<{
  children: React.ReactNode;
  center?: boolean;
  style?: React.CSSProperties;
}> = ({ children, center = false, style }) => (
  <AbsoluteFill
    style={{
      fontFamily: FONT,
      // `--spawn` and `-g` are commands a viewer retypes, and SF Mono renders a double hyphen as
      // one long dash when ligatures are on. Killing them here covers every mono run in the video,
      // because font-variant-ligatures inherits.
      fontVariantLigatures: "none",
      color: C.ink,
      padding: `96px 132px ${CAPTION_SAFE}px`,
      justifyContent: "center",
      // `stretch`, not `flex-start`. A flex column with `flex-start` shrinks every block child to
      // its own content width, which silently collapsed the tool chain, the waveform card and the
      // use-case grid to about a quarter of the frame — each of them looked deliberately narrow
      // rather than broken, which is how it survived the first three stills.
      alignItems: center ? "center" : "stretch",
      textAlign: center ? "center" : "left",
      ...style,
    }}
  >
    {children}
  </AbsoluteFill>
);

