/** A cursor that blinks on a 30-frame cycle, for the terminal scene. */
export const Caret: React.FC<{ color?: string }> = ({ color = C.green }) => {
  const frame = useCurrentFrame();
  return (
    <span
      style={{
        display: "inline-block",
        width: 18,
        height: 40,
        marginLeft: 6,
        verticalAlign: "-6px",
        backgroundColor: color,
        opacity: frame % 30 < 16 ? 1 : 0.15,
      }}
    />
  );
};
